-- RAVA Commerce Core V1: catalog, inventory, carts and orders. Payment gateway comes in a separate adapter layer.
create table if not exists public.product_categories(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,name text not null,slug text not null,status text not null default 'active' check(status in('active','hidden')),sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,slug));
create table if not exists public.products(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,category_id uuid references public.product_categories(id) on delete set null,name text not null,slug text not null,sku text,summary text not null default '',description text not null default '',price bigint not null default 0 check(price>=0),compare_at_price bigint check(compare_at_price is null or compare_at_price>=0),currency text not null default 'IRR',stock_quantity int not null default 0 check(stock_quantity>=0),track_inventory boolean not null default true,status text not null default 'draft' check(status in('draft','published','archived')),featured boolean not null default false,cover_url text,created_by uuid references auth.users(id) on delete set null,updated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz,unique(tenant_id,slug));
create table if not exists public.carts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,session_key text not null,status text not null default 'open' check(status in('open','converted','abandoned')),currency text not null default 'IRR',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,session_key));
create table if not exists public.cart_items(id uuid primary key default gen_random_uuid(),cart_id uuid not null references public.carts(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,quantity int not null check(quantity>0),unit_price bigint not null check(unit_price>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(cart_id,product_id));
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete restrict,order_number bigint generated by default as identity,status text not null default 'pending' check(status in('pending','awaiting_payment','paid','processing','shipped','completed','cancelled','refunded')),payment_status text not null default 'unpaid' check(payment_status in('unpaid','pending','paid','failed','refunded','partial_refund')),currency text not null default 'IRR',subtotal bigint not null default 0,discount_total bigint not null default 0,shipping_total bigint not null default 0,total bigint not null default 0,customer_name text not null,customer_email text,customer_phone text,shipping_address jsonb not null default '{}'::jsonb,notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),paid_at timestamptz,unique(tenant_id,order_number));
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,sku text,quantity int not null check(quantity>0),unit_price bigint not null check(unit_price>=0),line_total bigint not null check(line_total>=0));
create index if not exists products_tenant_status_idx on public.products(tenant_id,status,created_at desc);create index if not exists orders_tenant_status_idx on public.orders(tenant_id,status,created_at desc);create index if not exists carts_tenant_session_idx on public.carts(tenant_id,session_key);
alter table public.product_categories enable row level security;alter table public.products enable row level security;alter table public.carts enable row level security;alter table public.cart_items enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;
create policy product_categories_tenant_all on public.product_categories for all to authenticated using(public.can_access_tenant(tenant_id,null)) with check(public.can_access_tenant(tenant_id,null));
create policy products_tenant_all on public.products for all to authenticated using(public.can_access_tenant(tenant_id,null)) with check(public.can_access_tenant(tenant_id,null));
create policy carts_tenant_read on public.carts for select to authenticated using(public.can_access_tenant(tenant_id,null));
create policy orders_tenant_read on public.orders for select to authenticated using(public.can_access_tenant(tenant_id,null));
create policy order_items_tenant_read on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and public.can_access_tenant(o.tenant_id,null)));
-- Cart/order public mutations intentionally have no direct RLS write policy; trusted server functions will validate tenant, price, stock and anti-abuse controls.
